{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C45"],
      "claim": "A comparative bioavailability study reported pyridostigmine oral bioavailability of 7.6%, directly below the 20% threshold for the query molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "In fasting myasthenic patients, neostigmine, a closely related quaternary ammonium dimethylcarbamate, had absolute oral bioavailability of 2.0 ± 0.33%, supporting poor oral absorption for this charged carbamate class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Rivastigmine, a tertiary amine carbamate, showed high absolute oral bioavailability (71.7%), but it lacks the permanent quaternary charge of the query, so this high-F evidence has limited transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is pyridostigmine, a quaternary ammonium dimethylcarbamate. Direct comparative evidence gives pyridostigmine oral bioavailability ~7.6%, and the closely related quaternary carbamate neostigmine shows 1-2% absolute oral bioavailability under fasting conditions, both well below 20%. High-bioavailability carbamates such as rivastigmine lack the permanent positive charge and are not transferable to this quaternary query. Therefore the prediction is low.",
  "evidence_gaps": [
    "No dedicated absolute bioavailability study for pyridostigmine under fasted conditions is included; C45 is a comparative mention.",
    "Most neostigmine bioavailability data come from small patient cohorts rather than healthy volunteers.",
    "One neostigmine record reports 18.9%, but this remains below the 20% threshold and is outweighed by multiple consistent 1-2% estimates."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

